<template>
  <LabeledValueIcon :label="label || 'Date'" :icon="icon || CalendarIcon">
    {{ date ? processDate(date) : 'N/A' }}
  </LabeledValueIcon>
</template>
<script setup lang="ts">
import { CalendarIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';

const props = defineProps<{
  label?: string;
  date?: string | Date;
  icon?: any;
  /** Render only the date part (MM/dd/yyyy), dropping the time. */
  dateOnly?: boolean;
}>();

const { timezone } = useUserRole();

function processDate(date: string | Date) {
  if (date instanceof Date) {
    if (isNaN(date.getTime())) return 'N/A';
    const format = props.dateOnly ? 'MM/dd/yyyy' : 'MM/dd/yyyy, hh:mm aaa';
    return formatDateTzToFormat(date, format, timezone.value);
  }
  if (detectDateType(date) === 'invalid') return 'N/A';
  if (props.dateOnly && detectDateType(date) === 'iso') {
    return formatDateTzToFormat(date, 'MM/dd/yyyy', timezone.value);
  }
  return formatDateBasedOnType(date, timezone.value);
}
</script>
